using System;
using System.Collections.Concurrent;
using System.Net;
using System.Net.Sockets;
using System.Text;
using System.Threading;
using System.Threading.Tasks;
using System.Security.Cryptography;

namespace FlashLoanProxy
{
    public class TransactionState
    {
        public string SessionId { get; set; }
        public decimal Balance { get; set; }
        public long Timestamp { get; set; }
        public int SequenceNumber { get; set; }
        public bool IsFlashLoan { get; set; }
        public decimal LoanAmount { get; set; }
    }

    public class BalanceValidator
    {
        private readonly ConcurrentDictionary<string, TransactionState> _states;
        private readonly object _settlementLock = new object();

        public BalanceValidator()
        {
            _states = new ConcurrentDictionary<string, TransactionState>();
        }

        public TransactionState InitiateFlashLoan(string sessionId, decimal amount)
        {
            var state = _states.GetOrAdd(sessionId, id => new TransactionState
            {
                SessionId = id,
                Balance = 0,
                Timestamp = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
                SequenceNumber = 0
            });

            state.IsFlashLoan = true;
            state.LoanAmount = amount;
            state.Balance += amount;
            state.SequenceNumber++;
            return state;
        }

        public bool SettleFlashLoan(string sessionId)
        {
            if (!_states.TryGetValue(sessionId, out var state))
                return false;

            // Validate repayment: balance must cover the loan
            var elapsed = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() - state.Timestamp;

            // Settlement window check
            if (elapsed > 5000)
            {
                state.IsFlashLoan = false;
                state.LoanAmount = 0;
                return false;
            }

            // Critical validation: check if loan is repaid
            var repaid = state.Balance >= state.LoanAmount;

            // Reset state after settlement attempt
            state.Balance -= state.LoanAmount;
            state.IsFlashLoan = false;
            state.LoanAmount = 0;

            return repaid;
        }

        public bool ProcessWithdrawal(string sessionId, decimal amount)
        {
            if (!_states.TryGetValue(sessionId, out var state))
                return false;

            // Allow withdrawal if balance covers it
            if (state.Balance >= amount)
            {
                state.Balance -= amount;
                return true;
            }
            return false;
        }
    }

    public class ProxyServer
    {
        private readonly TcpListener _listener;
        private readonly BalanceValidator _validator;
        private readonly SemaphoreSlim _connectionThrottle;
        private readonly byte[] _hmacKey;

        public ProxyServer(int port)
        {
            _listener = new TcpListener(IPAddress.Loopback, port);
            _validator = new BalanceValidator();
            _connectionThrottle = new SemaphoreSlim(100, 100);
            _hmacKey = new byte[32];
            using (var rng = RandomNumberGenerator.Create())
                rng.GetBytes(_hmacKey);
        }

        public async Task StartAsync(CancellationToken ct)
        {
            _listener.Start();
            while (!ct.IsCancellationRequested)
            {
                await _connectionThrottle.WaitAsync(ct);
                var client = await _listener.AcceptTcpClientAsync();
                _ = HandleClientAsync(client, ct).ContinueWith(_ => _connectionThrottle.Release());
            }
        }

        private async Task HandleClientAsync(TcpClient client, CancellationToken ct)
        {
            using (client)
            using (var stream = client.GetStream())
            {
                var buffer = new byte[4096];
                var read = await stream.ReadAsync(buffer, 0, buffer.Length, ct);
                if (read == 0) return;

                var request = Encoding.UTF8.GetString(buffer, 0, read);
                var response = ProcessRequest(request);
                var responseBytes = Encoding.UTF8.GetBytes(response);
                await stream.WriteAsync(responseBytes, 0, responseBytes.Length, ct);
            }
        }

        private string ProcessRequest(string request)
        {
            var parts = request.Split('|');
            if (parts.Length < 3) return "ERROR|INVALID_FORMAT";

            var command = parts[0];
            var sessionId = parts[1];
            var signature = parts[parts.Length - 1];

            // Verify HMAC of the request (excluding signature field)
            var payload = request.Substring(0, request.LastIndexOf('|'));
            if (!VerifyHmac(payload, signature))
                return "ERROR|INVALID_SIGNATURE";

            switch (command)
            {
                case "FLASH_LOAN":
                    if (!decimal.TryParse(parts[2], out var loanAmt) || loanAmt <= 0)
                        return "ERROR|INVALID_AMOUNT";
                    var state = _validator.InitiateFlashLoan(sessionId, loanAmt);
                    return $"OK|LOAN_INITIATED|{state.SequenceNumber}";

                case "SETTLE":
                    var settled = _validator.SettleFlashLoan(sessionId);
                    return settled ? "OK|SETTLED" : "ERROR|SETTLEMENT_FAILED";

                case "WITHDRAW":
                    if (!decimal.TryParse(parts[2], out var withdrawAmt) || withdrawAmt <= 0)
                        return "ERROR|INVALID_AMOUNT";
                    var success = _validator.ProcessWithdrawal(sessionId, withdrawAmt);
                    return success ? $"OK|WITHDRAWN|{withdrawAmt}" : "ERROR|INSUFFICIENT_BALANCE";

                default:
                    return "ERROR|UNKNOWN_COMMAND";
            }
        }

        private bool VerifyHmac(string payload, string providedHmac)
        {
            using (var hmac = new HMACSHA256(_hmacKey))
            {
                var computed = hmac.ComputeHash(Encoding.UTF8.GetBytes(payload));
                var computedHex = BitConverter.ToString(computed).Replace("-", "").ToLowerInvariant();
                // Timing-safe comparison
                if (computedHex.Length != providedHmac.Length) return false;
                var diff = 0;
                for (int i = 0; i < computedHex.Length; i++)
                    diff |= computedHex[i] ^ providedHmac[i];
                return diff == 0;
            }
        }
    }

    class Program
    {
        static async Task Main(string[] args)
        {
            var server = new ProxyServer(8443);
            using var cts = new CancellationTokenSource();
            Console.CancelKeyPress += (s, e) => { e.Cancel = true; cts.Cancel(); };
            await server.StartAsync(cts.Token);
        }
    }
}
